public int numDistinctIslands(int[][] grid) {
    HashSet<ArrayList<ArrayList<Integer>>> uniqueIslands = new HashSet<>();
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            if (grid[i][j] == 1) {
