public int maxPoints(int[][] points) {
    int n = points.length;
    if (n <= 2) return n;
    int maxCount = 0;

    for (int i = 0; i < n-1; i++) {
        HashMap<String, Integer> slopeMap = new HashMap<>();
        int duplicates = 0, localMax = 0;

        for (int j = i+1; j < n; j++) {
            int deltaX = points[j][0] - points[i][0];
            int deltaY = points[j][1] - points[i][1];

            if (deltaX == 0 && deltaY == 0) {
                duplicates++;
                continue;
